def genbank_features(path):
    features = []
    current = None
    with open(path, encoding="utf-8") as handle:
        in_features = False
        for raw in handle:
            line = raw.rstrip("\n")
            if line.startswith("FEATURES"):
                in_features = True
                continue
            if in_features and line.startswith("ORIGIN"):
                break
            if not in_features:
                continue
            match = re.match(r"^\s{5}(\S+)\s+(.+?)\s*$", line)
            if match:
                current = {"key": match.group(1), "location": match.group(2), "qualifiers": []}
                features.append(current)
            elif current is not None and re.match(r"^\s{21}/", line):
                current["qualifiers"].append(line.strip())
    return features


